// Element constructors and value casts.
//
// Port of the `Construct` impls generated by typst-macros' `#[elem]` plus the
// hand-written `Construct` impls for `TextElem`, `PageElem`, and `LinkElem`.
// Field parsing order mirrors upstream `create_field_parser`:
// `#[parse]` → custom, `#[variadic]` → `args.all`, `#[required]` →
// `args.expect`, `#[positional]` → `args.find`, otherwise `args.named`.

import TypstSyntax
import TypstUtils

// MARK: - Casts

extension Spacing: Castable, IntoValue, FromValue {
    public static var input: CastInfo { .any }
    public static var output: CastInfo { .any }
    public static func castable(_ value: Value) -> Bool {
        Rel<Length>.castable(value) || Fr.castable(value)
    }
    public func intoValue() -> Value {
        switch self {
        case let .rel(rel):
            if rel.rel.isZero() { return rel.abs.intoValue() }
            if rel.abs == .zero { return rel.rel.intoValue() }
            return rel.intoValue()
        case let .fr(fr): return fr.intoValue()
        }
    }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        switch Rel<Length>.fromValue(value) {
        case let .success(rel): return .success(.rel(rel))
        case .failure:
            return Fr.fromValue(value).map { .fr($0) }
        }
    }
}

extension Parity: Castable, IntoValue, FromValue {
    public static var input: CastInfo { .type(Type.of(Str.self)) }
    public static var output: CastInfo { .type(Type.of(Str.self)) }
    public static func castable(_ value: Value) -> Bool {
        guard case let .str(s) = value else { return false }
        return Parity(rawValue: s.value) != nil
    }
    public func intoValue() -> Value { .str(Str(rawValue)) }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        guard case let .str(s) = value, let parity = Parity(rawValue: s.value)
        else { return .failure(error(value)) }
        return .success(parity)
    }
}

