extension DocumentFormat: Castable, IntoValue, FromValue {
    public static var input: CastInfo { .type(Type.of(Str.self)) }
    public static var output: CastInfo { .type(Type.of(Str.self)) }
    public var name: String {
        switch self {
        case .paged: return "paged"
        case .html: return "html"
        }
    }
    public static func castable(_ value: Value) -> Bool {
        guard case let .str(s) = value else { return false }
        return s.value == "paged" || s.value == "html"
    }
    public func intoValue() -> Value { .str(Str(name)) }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        guard case let .str(s) = value else { return .failure(error(value)) }
        switch s.value {
        case "paged": return .success(.paged)
        case "html": return .success(.html)
        default: return .failure(error(value))
        }
    }
}

extension Supplement: Castable, IntoValue, FromValue {
    public static var input: CastInfo { Content.input + Func.input }
    public static var output: CastInfo { .any }
    public static func castable(_ value: Value) -> Bool {
        Content.castable(value) || Func.castable(value)
    }
    public func intoValue() -> Value {
        switch self {
        case let .content(c): return .content(c)
        case let .function(f): return .function(f)
        }
    }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        switch Content.fromValue(value) {
        case let .success(c): return .success(.content(c))
        case .failure:
            return Func.fromValue(value).map { .function($0) }
        }
    }
}

extension Url: Castable, IntoValue, FromValue {
    public static var input: CastInfo { .type(Type.of(Str.self)) }
    public static var output: CastInfo { .type(Type.of(Str.self)) }
    public static func castable(_ value: Value) -> Bool {
        if case .str = value { return true }
        return false
    }
    public func intoValue() -> Value { .str(inner) }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        guard case let .str(s) = value else { return .failure(error(value)) }
        return Url.new(s).mapError { HintedString($0.message) }
    }
}

extension Destination: Castable, IntoValue, FromValue {
    public static var input: CastInfo { .any }
    public static var output: CastInfo { .any }
    public static func castable(_ value: Value) -> Bool {
        Url.castable(value) || Location.castable(value)
    }
    public func intoValue() -> Value {
        switch self {
        case let .url(url): return url.intoValue()
        case let .location(loc): return loc.intoValue()
        }
    }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        switch Url.fromValue(value) {
        case let .success(url): return .success(.url(url))
        case .failure:
            return Location.fromValue(value).map { .location($0) }
        }
    }
}

extension LinkTarget: Castable, IntoValue, FromValue {
    public static var input: CastInfo { Destination.input + Label.input }
    public static var output: CastInfo { .any }
    public static func castable(_ value: Value) -> Bool {
        Destination.castable(value) || Label.castable(value)
    }
    public func intoValue() -> Value {
        switch self {
        case let .dest(d): return d.intoValue()
        case let .label(l): return l.intoValue()
        }
    }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        switch Label.fromValue(value) {
        case let .success(label): return .success(.label(label))
        case .failure:
            return Destination.fromValue(value).map { .dest($0) }
        }
    }
}

// MARK: - List item casts

extension ListItem {
    /// Cast content to a list item: unpack an existing `item` element or
    /// wrap arbitrary content as the item's body. Port of upstream
    /// `cast! { ListItem, v: Content => ... }`.
    public static func fromContent(_ content: Content) -> ListItem {
        content.packed(ListItem.self) ?? ListItem(body: content)
    }
}

extension ListItem: Castable, IntoValue, FromValue {
    public static var input: CastInfo { Content.input }
    public static var output: CastInfo { Content.output }
    public static func castable(_ value: Value) -> Bool {
        Content.castable(value)
    }
    public func intoValue() -> Value { .content(Content(self)) }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        guard case let .content(c) = value else { return .failure(error(value)) }
        return .success(fromContent(c))
    }
}

extension EnumItem: Castable, IntoValue, FromValue {
    public static var input: CastInfo { Content.input }
    public static var output: CastInfo { Content.output }
    public static func castable(_ value: Value) -> Bool {
        Content.castable(value)
    }
    public func intoValue() -> Value { .content(Content(self)) }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        guard case let .content(c) = value else { return .failure(error(value)) }
        return .success(c.packed(EnumItem.self) ?? EnumItem(body: c))
    }
}

extension TermItem: Castable, IntoValue, FromValue {
    public static var input: CastInfo { Content.input }
    public static var output: CastInfo { Content.output }
    public static func castable(_ value: Value) -> Bool {
        Content.castable(value)
    }
    public func intoValue() -> Value { .content(Content(self)) }
    public static func fromValue(_ value: Value) -> HintedStrResult<Self> {
        guard case let .content(c) = value else { return .failure(error(value)) }
        guard let item = c.packed(TermItem.self) else {
            return .failure(HintedString("expected term item or array"))
        }
        return .success(item)
    }
}

// MARK: - Flush element

/// A flush marker placed by `place.flush()`. Port of `FlushElem` in
/// `layout/place.rs`. Registered under `place`'s scope once `PlaceElem`
/// lands; `PageElem`'s constructor emits it directly.
public struct FlushElem: NativeElement {
    public static let info = ElementInfo(
        name: "flush",
        title: "Flush",
        fields: [],
        capabilities: []
    )

    public var span: Span = .detached

    public init() {}

    public func field(_ id: UInt8) -> Value? { nil }

    public mutating func setField(_ id: UInt8, _ value: Value) throws {}

    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        try args.finishT()
        return Content(FlushElem())
    }
}

// MARK: - Constructs: spacing

extension HElem {
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        var elem = HElem(amount: try args.expectT("amount"))
        elem.weak = try args.namedT("weak") ?? false
        elem.span = args.span
        try args.finishT()
        return Content(elem)
    }
}

extension VElem {
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        var elem = VElem(amount: try args.expectT("amount"))
        elem.weak = try args.namedT("weak") ?? false
        // `attach` is internal upstream (`#[parse(Some(false))]`) — never set
        // from arguments.
        elem.span = args.span
        try args.finishT()
        return Content(elem)
    }
}

// MARK: - Constructs: page & breaks

extension PagebreakElem {
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        var elem = PagebreakElem()
        elem.weak = try args.namedT("weak") ?? false
        elem.to = try args.namedT("to") ?? nil
        // `boundary` is internal upstream (`#[parse(None)]`) — never set.
        elem.span = args.span
        try args.finishT()
        return Content(elem)
    }
}

extension PageElem {
    /// The page constructor is special: it doesn't create a page element.
    /// Instead, it ensures the passed content lives on a separate page and
    /// styles it. Port of upstream's hand-written `Construct` impl.
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        let styles = try Element(PageElem.self).setStyles(engine: &engine, args: &args)
        let body: Content = try args.expectT("body")
        return Content.sequence([
            PagebreakElem.sharedWeak,
            Content(FlushElem()),
            body,
            PagebreakElem.sharedBoundary,
        ]).styledWithMap(styles)
    }
}

// MARK: - Constructs: containers

extension AlignElem {
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        // `alignment` is `#[positional]` upstream and must be consumed before
        // the required `body`.
        let alignment: Alignment = try args.findT() ?? .default
        let body: Content = try args.expectT("body")
        var elem = AlignElem(alignment: alignment, body: body)
        elem.span = args.span
        try args.finishT()
        return Content(elem)
    }
}

