extension LinkElem {
    /// Custom `#[parse]` impls upstream: `dest` is a required positional
    /// `LinkTarget`; `body` defaults to the URL's text for URL destinations.
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        let dest: LinkTarget = try args.expectT("destination")
        let body: Content
        switch dest {
        case let .dest(.url(url)):
            body = try args.eatT() ?? bodyFromUrl(url)
        default:
            body = try args.expectT("body")
        }
        var elem = LinkElem(dest: dest, body: body)
        elem.span = args.span
        try args.finishT()
        return Content(elem)
    }
}

