// MARK: - Constructs: text & document

extension TextElem {
    /// The text constructor is special: it doesn't create a text element.
    /// Instead, it styles all text in the passed body. Port of upstream's
    /// hand-written `Construct` impl.
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        let styles = try Element(TextElem.self).setStyles(engine: &engine, args: &args)
        let body: Content = try args.expectT("body")
        return body.styledWithMap(styles)
    }
}

/// Parse a `OneOrMultiple<EcoString>`-style argument: a string becomes a
/// single-element list, an array becomes the list. Port helper for
/// `document`'s `author`/`keywords` fields.
private func namedStringList(_ args: inout Args, _ name: String) throws -> [Str]? {
    guard let value: Value = try args.namedT(name) else { return nil }
    switch value {
    case let .str(s): return [s]
    case let .array(a):
        var list: [Str] = []
        for item in a.items {
            guard case let .str(s) = item else {
                throw bailHint("expected string or array of strings for \(name)")
            }
            list.append(s)
        }
        return list
    default:
        throw bailHint("expected string or array of strings for \(name)")
    }
}

extension DocumentElem {
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        var elem = DocumentElem(body: try args.expectT("body"))
        elem.title = try args.namedOpt("title")
        elem.author = try namedStringList(&args, "author") ?? []
        elem.description = try args.namedOpt("description")
        elem.keywords = try namedStringList(&args, "keywords") ?? []
        elem.date = try args.namedT("date") ?? .auto
        elem.format = try args.namedT("format") ?? .auto
        elem.span = args.span
        try args.finishT()
        return Content(elem)
    }
}


// MARK: - Constructs: grid & table

/// Shared gutter-fallback parse for `grid`/`table` set rules: `gutter`
/// feeds `column-gutter` and `row-gutter` when they are absent
/// (upstream `#[parse]` on `column_gutter`/`row_gutter`).
func gutterFallback<T: FromValue>(_ args: inout Args,
                                           column: String,
                                           row: String) throws
    -> (column: T?, row: T?) {
    let gutter: T? = try args.namedT("gutter")
    let columnValue: T? = try args.namedT(column) ?? gutter
    let rowValue: T? = try args.namedT(row) ?? gutter
    return (columnValue, rowValue)
}

extension GridElem {
    public static func construct(engine: inout Engine, args: inout Args) throws -> Content {
        var elem = GridElem()
        elem.columns = try args.namedT("columns") ?? elem.columns
        elem.rows = try args.namedT("rows") ?? elem.rows
        let gutters: (TrackSizings?, TrackSizings?) = try gutterFallback(
            &args, column: "column-gutter", row: "row-gutter")
        elem.columnGutter = gutters.0 ?? elem.columnGutter
        elem.rowGutter = gutters.1 ?? elem.rowGutter
        elem.inset = try args.namedT("inset") ?? elem.inset
        elem.align = try args.namedT("align") ?? elem.align
        elem.fill = try args.namedT("fill") ?? elem.fill
        elem.stroke = try args.namedT("stroke") ?? elem.stroke
        elem.children = try args.allT()
        elem.span = args.span
        try args.finishT()
        return Content(elem)
    }
}

