// MARK: - Element scopes & registration

extension ListElem {
    /// Upstream `#[scope] impl ListElem { #[elem] type ListItem; }`.
    static var itemScope: Scope {
        let scope = Scope()
        scope.define("item", .function(Func(element: Element(ListItem.self))))
        return scope
    }
}

extension EnumElem {
    static var itemScope: Scope {
        let scope = Scope()
        scope.define("item", .function(Func(element: Element(EnumItem.self))))
        return scope
    }
}

extension TermsElem {
    static var itemScope: Scope {
        let scope = Scope()
        scope.define("item", .function(Func(element: Element(TermItem.self))))
        return scope
    }
}

/// Register an element function under its upstream name.
private func defineElement<T: NativeElement>(into global: Scope, _ type: T.Type = T.self) {
    let element = Element(T.self)
    global.define(element.name, .function(element.function))
}

/// Port of upstream `model/mod.rs` + `text/mod.rs` element registration for
/// the elements ported so far.
func defineModelElements(into global: Scope) {
    defineElement(into: global, DocumentElem.self)
    defineElement(into: global, ParElem.self)
    defineElement(into: global, ParbreakElem.self)
    defineElement(into: global, StrongElem.self)
    defineElement(into: global, EmphElem.self)
    defineElement(into: global, ListElem.self)
    defineElement(into: global, EnumElem.self)
    defineElement(into: global, TermsElem.self)
    defineElement(into: global, TableElem.self)
    defineElement(into: global, LinkElem.self)
    defineElement(into: global, RefElem.self)
    defineElement(into: global, HeadingElem.self)
    defineElement(into: global, CiteElem.self)
    defineElement(into: global, LinebreakElem.self)
    defineElement(into: global, SmartQuoteElem.self)
    defineElement(into: global, TextElem.self)
    defineElement(into: global, UnderlineElem.self)
    defineElement(into: global, OverlineElem.self)
    defineElement(into: global, StrikeElem.self)
    defineElement(into: global, HighlightElem.self)
    defineElement(into: global, SubElem.self)
    defineElement(into: global, SuperElem.self)
    defineElement(into: global, SmallcapsElem.self)
    defineElement(into: global, DividerElem.self)
    defineElement(into: global, QuoteElem.self)
}

/// Port of upstream `layout/mod.rs` element registration for the elements
/// ported so far.
func defineLayoutElements(into global: Scope) {
    defineElement(into: global, PageElem.self)
    defineElement(into: global, PagebreakElem.self)
    defineElement(into: global, VElem.self)
    defineElement(into: global, HElem.self)
    defineElement(into: global, BoxElem.self)
    defineElement(into: global, BlockElem.self)
    defineElement(into: global, AlignElem.self)
    defineElement(into: global, PadElem.self)
    defineElement(into: global, StackElem.self)
    defineElement(into: global, HideElem.self)
    defineElement(into: global, PlaceElem.self)
    defineElement(into: global, ColumnsElem.self)
    defineElement(into: global, ColbreakElem.self)
    defineElement(into: global, RepeatElem.self)
    defineElement(into: global, MoveElem.self)
    defineElement(into: global, ScaleElem.self)
    defineElement(into: global, RotateElem.self)
    defineElement(into: global, SkewElem.self)
    defineElement(into: global, LayoutElem.self)
    defineElement(into: global, GridElem.self)

    // Upstream `lib.rs` global prelude: alignment and direction values.
    global.define("ltr", .dynamic(Dir.ltr))
    global.define("rtl", .dynamic(Dir.rtl))
    global.define("ttb", .dynamic(Dir.ttb))
    global.define("btt", .dynamic(Dir.btt))
    global.define("start", .dynamic(Alignment.start))
    global.define("left", .dynamic(Alignment.left))
    global.define("center", .dynamic(Alignment.center))
    global.define("right", .dynamic(Alignment.right))
    global.define("end", .dynamic(Alignment.end))
    global.define("top", .dynamic(Alignment.top))
    global.define("horizon", .dynamic(Alignment.horizon))
    global.define("bottom", .dynamic(Alignment.bottom))
}

